package org.kanger.storage.dumb2;
import java.nio.file.*;
import java.util.*;
import org.kanger.*;

/** Native connection profile only; the full symbolic family admission gate remains closed. */
public final class SymbolicCacheConnectionInspectionRunner {
    private static int checks;
    private static final String RULES="!@u rel(1,u,1)->middle(u); !@u middle(u)->tail(u);";
    private static final String PRIVATE="!$u rel(1,u,1);";
    private static void need(boolean yes,String reason){checks++;if(!yes)throw new AssertionError(reason);}
    private static Mind open(DB db,Path directory,String name)throws Exception{User u=new User();u.setDatabaseDir(directory.toString()+java.io.File.separator);db.init(u);Mind root=new Mind(u);u.setCurrentMind(root);Mind m=(Mind)root.useStorage(name);u.setCurrentMind(m);return m;}
    private static void close(Mind m)throws Exception{((User)m.getUser()).setCurrentMind(m.closeStorage());}
    private static void seed(Path directory,String name,String text)throws Exception{DB db=new DB();Mind m=open(db,directory,name);try{need(m.compile(text,null,false),"physical fixture "+name);}finally{close(m);}}
    private static boolean refuses(SymbolicCacheConnectionInspection result,DB db,Mind source)throws Exception{try{result.requireCurrent(db,source);return false;}catch(Exception expected){return true;}}
    private static void run()throws Exception{
        Path directory=Files.createTempDirectory("symbolic-foreign-initialized-");seed(directory,"Source","!marker(1);");seed(directory,"Target",RULES);DB db=new DB();Mind source=open(db,directory,"Source");long targetPin,published;SymbolicCacheConnectionInspection saved;
        try{
            targetPin=db.versionHistory("Target").getCurrentRevision();db.connectContext("Target");db.saveConnections(source);SymbolicCacheConnectionInspection bare=db.inspectConnectedSymbolicCache(source,"Target");need(!bare.working.inventory.localX&&bare.initialization.isEmpty()&&bare.targetRevision==targetPin,"actual foreign role and exact empty-recipe pin retained");bare.requireCurrent(db,source);
            db.applyConnectionCommand(source,"Target",PRIVATE);need(refuses(bare,db,source),"private recipe/layer extension invalidates the old empty view");long sourceRevision=db.getRevision();String sourceBefore=ContextProductionInventory.inspect(source,db.getContextId(),sourceRevision,true,Collections.emptyList(),1000).fingerprint;
            SymbolicCacheConnectionInspection first=db.inspectConnectedSymbolicCache(source,"Target");first.requireCurrent(db,source);need(first.initialization.equals(Collections.singletonList(PRIVATE))&&first.working.inventory.initialization.equals(first.initialization)&&!first.working.inventory.localX,"full private recipe and foreign role survive proof-local replay");need(first.working.inventory.generated.size()==2&&first.working.evidence.ledger.productRows==2&&!first.working.inventory.dependentPrimaryView(),"real initialized symbolic consequences checked without inventory promotion");need(first.coldProof.evidence.products.size()==2&&first.coldProof!=first.working.evidence.proof,"independent exact-pin/full-recipe reconstruction gets its own complete proof");
            need(sourceRevision==db.getRevision()&&sourceBefore.equals(ContextProductionInventory.inspect(source,db.getContextId(),sourceRevision,true,Collections.emptyList(),1000).fingerprint)&&targetPin==db.versionHistory("Target").getCurrentRevision(),"read-only effective-view check changes neither source nor target publication");
            db.applyConnectionCommand(source,"Target","!private(2);");need(refuses(first,db,source),"second private command cannot reuse first recipe evidence");saved=db.inspectConnectedSymbolicCache(source,"Target");need(saved.initialization.equals(Arrays.asList(PRIVATE,"!private(2);"))&&saved.working.inventory.primary.size()==4,"complete two-command recipe rebuilt, not only last command");boolean immutable=false;try{saved.initialization.clear();}catch(UnsupportedOperationException expected){immutable=true;}need(immutable,"provider recipe evidence immutable");
            published=db.saveConnections(source);need(refuses(saved,db,source),"source publication requires fresh source-frame evidence");saved=db.inspectConnectedSymbolicCache(source,"Target");need(saved.sourceRevision==published,"fresh source frame uses actual published revision");
            seed(directory,"Target","!future(9);");need(db.versionHistory("Target").getCurrentRevision()>targetPin,"target CURRENT advanced independently");saved.requireCurrent(db,source);SymbolicCacheConnectionInspection pinned=db.inspectConnectedSymbolicCache(source,"Target");need(pinned.targetRevision==targetPin&&pinned.working.inventory.primary.stream().noneMatch(row->"!future(9);".equals(row.origin)),"old selected pin and private recipe stay exact after target advances");
            db.switchContextRevision("Target",db.versionHistory("Target").getCurrentRevision());need(refuses(pinned,db,source),"switching actual target pin invalidates old effective evidence");SymbolicCacheConnectionInspection switched=db.inspectConnectedSymbolicCache(source,"Target");need(switched.targetRevision>targetPin&&switched.initialization.equals(Arrays.asList(PRIVATE,"!private(2);"))&&switched.working.inventory.primary.size()==5,"fresh switched view replays full recipe on the new pin");published=db.saveConnections(source);saved=db.inspectConnectedSymbolicCache(source,"Target");
        }finally{close(source);}
        need(refuses(saved,db,source),"closed owning adapter cannot reuse connection evidence");db=new DB();source=open(db,directory,"Source");try{need(db.getRevision()==published,"saved source revision reopened");SymbolicCacheConnectionInspection reopened=db.inspectConnectedSymbolicCache(source,"Target");need(reopened.initialization.equals(Arrays.asList(PRIVATE,"!private(2);"))&&reopened.working.inventory.generated.size()==2&&reopened.working.inventory.primary.size()==5,"cold source reopen rebuilds exact published pin and full private symbolic recipe");need(refuses(saved,db,source),"new owning adapter requires new connection evidence");
            ContextConnection actual=db.dmzTopology().get(0);actual.closeLayer();need(refuses(reopened,db,source),"retired target runtime cannot reuse old owner-bound snapshot");SymbolicCacheConnectionInspection rebuilt=db.inspectConnectedSymbolicCache(source,"Target");need(rebuilt.working!=reopened.working,"explicit fresh check recreates and proves the missing private runtime");db.disconnectContext("Target");need(refuses(rebuilt,db,source),"removed connection cannot reuse its evidence");db.connectContext("Target","team");boolean grouped=false;try{db.inspectConnectedSymbolicCache(source,"Target");}catch(org.kanger.exception.CommandErrorException expected){grouped=true;}need(grouped,"group/commune views require separate qualification");
        }finally{close(source);}
        DB targetDb=new DB();Mind target=open(targetDb,directory,"Target");try{ContextProductionInventory inventory=ContextProductionInventory.inspect(target,targetDb.getContextId(),targetDb.getRevision(),true,Collections.emptyList(),1000);need(inventory.primary.size()==3&&inventory.primary.stream().noneMatch(row->PRIVATE.equals(row.origin)||"!private(2);".equals(row.origin)),"private witness and assertion were never written to physical target");}finally{close(target);}
    }
    private static void refusals()throws Exception{
        Path directory=Files.createTempDirectory("symbolic-foreign-refusal-");seed(directory,"Source","!marker(1);");seed(directory,"Target",RULES+" !value(9);");final DB db=new DB();final Mind source=open(db,directory,"Source");
        try{
            db.connectContext("Target");db.saveConnections(source);db.applyConnectionCommand(source,"Target",PRIVATE);SymbolicCacheConnectionInspection initial=db.inspectConnectedSymbolicCache(source,"Target");need(source.compile("!sourceExtra(2);",null,false),"unpublished source-frame change");need(refuses(initial,db,source),"source inventory guard works even before its revision advances");final SymbolicCacheConnectionInspection checked=db.inspectConnectedSymbolicCache(source,"Target");
            final String frame=ContextProductionInventory.inspect(source,db.getContextId(),db.getRevision(),true,Collections.emptyList(),1000).fingerprint;
            ContextDependentForeignCacheSnapshotRunner.withNoGood(source,()->{
                need(frame.equals(ContextProductionInventory.inspect(source,db.getContextId(),db.getRevision(),true,Collections.emptyList(),1000).fingerprint),"source no-good leaves physical source fingerprint unchanged");need(refuses(checked,db,source),"source branch restriction cannot reuse foreign effective evidence");boolean blocked=false;try{db.inspectConnectedSymbolicCache(source,"Target");}catch(IllegalStateException expected){blocked=true;}need(blocked,"source branch restriction cannot create unrestricted foreign evidence");
            });checked.requireCurrent(db,source);
            ContextConnection connection=db.dmzTopology().get(0);Mind layer=connection.layer();org.kanger.units.Rule generated=null;org.kanger.interfaces.ITerm nine=null;for(org.kanger.interfaces.IRule item:layer.getRules()){org.kanger.units.Rule row=(org.kanger.units.Rule)item;if(item.isGenerated())generated=row;else if("!value(9);".equals(row.getOrigin()))nine=row.getDomain().getArguments().get(0).getValue(layer);}need(generated!=null&&nine!=null,"actual private cache and ordinary control value available");generated.getDomain().getArguments().set(0,new org.kanger.primitives.Argument(nine));need(refuses(checked,db,source),"actual private cache mutation invalidates old snapshot");
            long revision=db.getRevision(),targetRevision=db.versionHistory("Target").getCurrentRevision();String bad=ContextProductionInventory.inspect(layer,checked.targetContext,checked.targetRevision,false,checked.initialization,1000).fingerprint;boolean blocked=false;try{db.inspectConnectedSymbolicCache(source,"Target");}catch(IllegalStateException expected){blocked=true;}need(blocked,"fresh cold comparison cannot bless an unproved private cache value");need(revision==db.getRevision()&&targetRevision==db.versionHistory("Target").getCurrentRevision()&&bad.equals(ContextProductionInventory.inspect(layer,checked.targetContext,checked.targetRevision,false,checked.initialization,1000).fingerprint),"foreign refusal changes neither cache, source revision nor physical target");
        }finally{close(source);}
    }
    public static void main(String[] args)throws Exception{System.setProperty("user.home",Files.createTempDirectory("symbolic-connection-driver-").toString());run();refusals();System.out.println("SYMBOLIC_CACHE_CONNECTION_INSPECTION_PASS checks="+checks);}
}
